THOUGHT: The test is failing because I haven't created the database tables. But that's not the point of this test. The point is to check if the filtering logic works correctly. Let me modify the test to avoid database operations and focus on the logic:

```bash
cat <<'EOF' > test_pr_issue.py
import os
import sys
import django
from django.conf import settings
from unittest.mock import Mock, MagicMock

# Configure Django settings
if not settings.configured:
    settings.configure(
        DEBUG=True,
        DATABASES={
            'default': {
                'ENGINE': 'django.db.backends.sqlite3',
                'NAME': ':memory:',
            }
        },
        INSTALLED_APPS=[
            'rest_framework',
            'rest_framework_nested',
        ],
        USE_TZ=True,
        SECRET_KEY='fake-key',
    )

django.setup()

from rest_framework_nested.viewsets import NestedViewSetMixin
from rest_framework import viewsets

# Mock the queryset filtering
class MockQuerySet:
    def __init__(self, items=None):
        self.items = items or []

    def filter(self, **kwargs):
        # Simplified filtering logic for testing
        print(f"Applying filter: {kwargs}")
        return MockQuerySet(self.items)

    def count(self):
        return len(self.items)

    def all(self):
        return self

class ChildViewSet(NestedViewSetMixin, viewsets.ViewSet):
    parent_lookup_kwargs = {'parent_pk': 'parent__pk'}

    def get_queryset(self):
        return MockQuerySet()

# Test the viewset
try:
    # Test the viewset filtering logic
    viewset = ChildViewSet()
    viewset.kwargs = {'parent_pk': 1}
    viewset.swagger_fake_view = False

    # Mock the parent method
    viewset._get_parent_lookup_kwargs = MagicMock(return_value={'parent_pk': 'parent__pk'})

    queryset = viewset.get_queryset()
    print("get_queryset() called successfully")

    # Check if the method is called in the right order
    if hasattr(viewset, '_get_parent_lookup_kwargs') and viewset._get_parent_lookup_kwargs.called:
        print("SUCCESS: parent_lookup_kwargs retrieved correctly")
    else:
        print("INFO: Testing call order...")

except Exception as e:
    print(f"Error: {e}")
    import traceback
    traceback.print_exc()
EOF
